package com.bank.gotcha.service;

import com.bank.gotcha.model.Employee;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;
import java.util.logging.Logger;

public class SqlGotchaDemo {
    private static final Logger log = Logger.getLogger(SqlGotchaDemo.class.getName());
    private final List<Employee> emps = List.of(
        new Employee(1, "Rajesh", new BigDecimal("120000"), new BigDecimal("5000"), 10),
        new Employee(2, "Priya",  new BigDecimal("150000"), null, 0),
        new Employee(3, "Amit",   new BigDecimal("110000"), new BigDecimal("3000"), 4)
    );

    // Trap 1: bonus = NULL never matches; IS NULL does.
    public void nullComparison() {
        long buggy = emps.stream().filter(e -> e.bonus != null && e.bonus.equals(null)).count(); // always 0
        long correct = emps.stream().filter(e -> e.bonus == null).count();                        // IS NULL
        log.info("bonus = NULL matches " + buggy + " (buggy); bonus IS NULL matches " + correct);
    }

    // Trap 2: NOT IN with a NULL in the list returns nothing.
    public void notInWithNull() {
        Set<BigDecimal> excludeList = new HashSet<>(Arrays.asList(new BigDecimal("3000"), null));
        // SQL NOT IN: if list has NULL, NOT IN is never true → zero results.
        long sqlNotIn = excludeList.contains(null) ? 0
                : emps.stream().filter(e -> e.bonus != null && !excludeList.contains(e.bonus)).count();
        long notExistsFix = emps.stream()
                .filter(e -> e.bonus != null && !new BigDecimal("3000").equals(e.bonus)).count();
        log.info("NOT IN (with NULL) → " + sqlNotIn + " rows (buggy); NOT EXISTS fix → " + notExistsFix);
    }

    // Trap 3: safe division with NULLIF(txns, 0).
    public void safeDivision() {
        for (Employee e : emps) {
            BigDecimal feePerTxn = e.txns == 0 ? null  // NULLIF(txns,0) → NULL → result NULL
                    : e.salary.divide(BigDecimal.valueOf(e.txns), 2, RoundingMode.HALF_UP);
            log.info(e.name + " fee/txn = " + (feePerTxn == null ? "NULL (no divide-by-zero)" : feePerTxn));
        }
    }

    // Trap 5: COUNT(*) vs COUNT(bonus) vs COUNT(DISTINCT bonus).
    public void countVariants() {
        long countStar = emps.size();                                             // 3
        long countBonus = emps.stream().filter(e -> e.bonus != null).count();     // 2 (ignores NULL)
        long countDistinct = emps.stream().map(e -> e.bonus).filter(Objects::nonNull).distinct().count(); // 2
        log.info("COUNT(*)=" + countStar + " COUNT(bonus)=" + countBonus + " COUNT(DISTINCT bonus)=" + countDistinct);
    }

    // Trap 6: SUM ignores NULL.
    public void sumIgnoresNull() {
        BigDecimal sum = emps.stream().map(e -> e.bonus).filter(Objects::nonNull)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        log.info("SUM(bonus) = " + sum + " (Priya's NULL ignored)");
    }
}
